import json
import datetime

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def read_json(path):
    try:
        return json.loads(api.files.read(file=path, scope="org") or "null")
    except Exception:
        return None

def comment(body):
    try:
        api.workq.comment(todo_id=todo_id, body=body)
    except Exception:
        pass

slug = str(params["slug"] or "")
todo_id = str(params["todo_id"] or "")
request = params["request"] or {}
decision = str(params["decision"] or "")
edited_message = str(params.get("edited_message") or "").strip()

referral = request.get("referral") or {}
drafts = request.get("drafts") or {}
patient_name = str(request.get("patient_name") or "")
settings = read_json("PracticeManager/Practices/" + slug + ".json") or {}
practice_name = str(settings.get("name") or "")
cfg = settings.get("referral_watchdog") or {}
remind_after_days = int(cfg.get("follow_up_days", 5))
now = datetime.datetime.now(datetime.timezone.utc)
followup_path = "PracticeManager/State/" + slug + "-referral-followup-" + todo_id + ".json"

outcome = ""
recipient = ""
if decision == "Don't send":
    outcome = "rejected"
    try:
        api.workq.complete(todo_id=todo_id)
    except Exception:
        pass
elif read_json(followup_path):
    outcome = "already_sent"
    comment("This referral request was already sent, so nothing was sent again.")
else:
    to_gp = decision == "Send to GP"
    recipient = str((request.get("gp_email") if to_gp else request.get("patient_email")) or "")
    text = edited_message or str(drafts.get("gp" if to_gp else "patient") or "")
    if not recipient:
        outcome = "no_email"
        comment("Nothing was sent: there's no email on file for the " + ("GP" if to_gp else "patient")
                + ". Add it in Cliniko and submit the form again, or contact them another way.")
    elif not text:
        outcome = "no_text"
        comment("Nothing was sent: there was no message text.")
    else:
        subject = ("Referral request for " + patient_name if to_gp else "Your " + str(referral.get("referral_type") or "") + " referral").strip()
        subject = subject + (" - " + practice_name if practice_name else "")
        try:
            api.connectors.invoke(server="m365-mail-send", tool="send_email",
                                  args={"to": [recipient], "subject": subject, "body": text, "contentType": "Text"})
            outcome = "sent"
        except Exception as exc:
            outcome = "send_failed"
            comment("The email to " + recipient + " failed to send: " + str(exc)[:300])

    if outcome == "sent":
        # Handoff to "Follow up referral requests": watches Cliniko for the new
        # referral and reminds the manager if it hasn't arrived in time.
        api.files.put(file=followup_path, scope="org", content=json.dumps({
            "slug": slug, "todo_id": todo_id, "status": "waiting",
            "patient_id": str(referral.get("patient_id") or ""), "patient_name": patient_name,
            "case_id": str(referral.get("case_id") or ""), "expiry_date": str(referral.get("expiry_date") or ""),
            "max_sessions": referral.get("max_sessions"), "referral_type": str(referral.get("referral_type") or ""),
            "sent_to": "gp" if to_gp else "patient", "recipient": recipient,
            "sent_at": zulu(now), "remind_at": zulu(now + datetime.timedelta(days=remind_after_days)),
        }, indent=2, sort_keys=True))
        comment("Referral request sent to the " + ("GP" if to_gp else "patient") + " (" + recipient + "). "
                + "This item stays open until a new referral appears in Cliniko; you'll get a reminder here if it hasn't after "
                + str(remind_after_days) + " days.")
        try:
            api.workq.set_status(todo_id=todo_id, status="in_progress")
        except Exception:
            pass

# Audit trail (healthcare-practice-management-guardrail-audit format).
tz_name = str(settings.get("timezone") or "UTC")
try:
    from zoneinfo import ZoneInfo
    today_str = now.astimezone(ZoneInfo(tz_name)).date().isoformat()
except Exception:
    today_str = now.date().isoformat()
audit_path = "PracticeManager/AuditLog/" + slug + "-" + today_str + ".jsonl"
try:
    existing_log = api.files.read(file=audit_path, scope="org")
except Exception:
    existing_log = ""
try:
    api.files.put(file=audit_path, scope="org", content=existing_log + json.dumps({
        "ts": zulu(now), "practice_slug": slug, "actor": "agent",
        "source": "automation:Cliniko Automations: Send approved referral request",
        "action": "sent" if outcome == "sent" else ("rejected" if outcome == "rejected" else "blocked"),
        "target": {"kind": "patient_case", "id": str(referral.get("case_id") or "")},
        "summary": "Referral request for " + patient_name + ": " + outcome + (" to " + recipient if recipient else ""),
        "guardrails": [{"rule": "patient_facing_requires_approval", "result": "pass", "detail": "sent only after the manager's form approval"}],
        "workq_item_id": todo_id,
    }, sort_keys=True) + "\n")
except Exception:
    pass
